mapper.select:
select
con.Con_Name as conName,
con.Con_Code as conCode,

c1.C_Name_History as claimFpNameHistory,
c2.C_Name_History as claimSpNameHistory,
c1.C_Name as claimFpName,
c2.C_Name as claimSpName,
c1.C_Abbreviation as claimFpAbbName,
c2.C_Abbreviation as claimSpAbbName,
mn.*
from  Pc_Claim mn
left join  Con_Contract con on con.Con_Id=mn.Con_Id

left join  SYS_Company c1 on c1.C_Id=mn.Claim_Fp
left join  SYS_Company c2 on c2.C_Id=mn.Claim_Sp
${params.authSql}

    and mn.Te_Id = #{params.teId}


    and mn.P_Id=#{params.pId}


    and mn.Claim_Type=#{params.claimType}


    and mn.Claim_Fp=#{params.claimFp}


    and mn.Claim_Sp=#{params.claimSp}


    
        
            and likePname(#{params.pName},pro.P_Id)=true
        
        
            and pro.P_Name like concat('%',#{params.pName},'%')
        
    


    and con.Con_Name like concat('%',#{params.conName},'%')


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Claim_Create_Time desc
